// Agent Session Demo — the reference for anna.agent.session: every session
// interface over BOTH channels, driven by the same code.
//
//   Host API     page ── anna.agent.session.* ─────────────────────▶ host
//   Reverse RPC  page ── anna.tools.invoke ─▶ bundled Executa ─ agent/session.* ─▶ host
//
// Each channel is an ADAPTER with the same eleven methods (create, attach,
// list, refresh, run, cancel, history, delete, run_status, frames, catalog).
// The sections below only ever call `channel.<method>()` — there is no
// per-channel branch in them. Inside an App the page and the Executas it
// invokes share sessions, so switching channel keeps the session: the new
// channel simply `attach`es the same uuid.
//
// The workspace practices the walkthrough demonstrates (forum /t/174 path
// determinism, /t/86 zero-tools, /t/191 empty completions + working cancel):
//   1. PIN the session to one filesystem client (submode "fixed" +
//      fixed_client_id) so every run targets the same workspace root.
//   2. DISCOVER the workspace root first; afterwards every instruction
//      embeds ABSOLUTE paths under it — never assume "~" or a relative CWD.
//   3. VERIFY writes with a nonce read-back in an independent run; compare
//      in app code. A "task completed" claim is not proof the file changed.
//   4. STOP on structured tool errors (error_code PATH_OUTSIDE_SANDBOX /
//      NOT_FOUND + sandbox_root) — never fall back to a similar path.
//   5. CLASSIFY the terminal state of every run: in-run error frames
//      (empty_completion is a retryable infrastructure error, NOT a business
//      failure), gate errors, and task_cancelled as a distinct outcome.
//
// This bundle is loaded as a native ES module and imports the Anna App
// Runtime SDK directly. `.connect()` performs the host handshake.

import { AnnaAppRuntime } from "/static/anna-apps/_sdk/latest/index.js";

// `anna-tool-ids.js` (generated by `anna-app dev` / `apps publish`) maps the
// bundled handle to the server-minted tool_id. The literal is only a
// fallback for runs where no sidecar is present.
const EXECUTA_HANDLE = "session-via-executa";
const EXECUTA_TOOL_ID =
  (window.__ANNA_TOOL_IDS__ && window.__ANNA_TOOL_IDS__[EXECUTA_HANDLE]) ||
  "tool-test-session-via-executa-12345678";
// One tools.invoke holds a whole agent turn on the Reverse RPC channel; this
// is the platform's per-invoke ceiling. Longer turns: run.status → frames.
const EXECUTA_RUN_TIMEOUT_MS = 180000;

const $ = (id) => document.getElementById(id);
const errBox = $("errors");
const uuidInput = $("session-uuid-input");
const statusEl = $("session-status");
const lifecycleEl = $("session-lifecycle");
const toolsEl = $("session-tools");
const toolsWarnEl = $("tools-warning");
const sessionListEl = $("session-list");
const submodeSel = $("submode-sel");
const fixedRow = $("fixed-client-row");
const rootStatusEl = $("root-status");
const writeTargetEl = $("write-target");
const verdictEl = $("verify-verdict");
const channelSel = $("channel-sel");
const channelStatusEl = $("channel-status");

const SUBMODE_HINTS = {
  auto:
    "Host resolves the agent (user default / cloud). Fine for text tasks; for file editing prefer 'fixed' so reads and writes cannot silently switch to a different machine's workspace mid-session.",
  fixed:
    "All runs in this session are pinned to ONE client_id — the strongest guarantee that every fs operation targets the same workspace root (forum /t/174).",
};

const CHANNEL_HINTS = {
  host:
    "The page calls the host directly. Frames reach the page one by one while the run is in flight.",
  executa:
    "The page invokes the bundled Executa's agent_session tool; the Executa issues the agent/session.* reverse RPC. Frames reach the EXECUTA live (agent/session.frame), but one tools.invoke answers once — so the page receives them together, when the turn ends (≤ 180s per invoke; recover longer turns with run status → replay frames).",
};

// ── Session-level system prompt: the path-discipline floor every
//    file-editing app should ship. Applied to every run in the session.
const DEFAULT_SYSTEM_PROMPT = `You are a workspace file assistant. Path discipline (MANDATORY):
1. Always call filesystem tools with ABSOLUTE paths, exactly as given. Never trim a path to a relative one, never substitute a root you assume is correct.
2. If a filesystem tool fails (e.g. error_code PATH_OUTSIDE_SANDBOX or NOT_FOUND), report the structured error VERBATIM (including path and sandbox_root when present) and STOP. Never retry with a rewritten path and never fall back to a similarly named file or directory.
3. When asked to reply with JSON, output ONLY the JSON object on a single line — no markdown fences, no commentary.`;

const annaReady = (async () => {
  const anna = await AnnaAppRuntime.connect();
  window.anna = anna;
  return anna;
})().catch((err) => {
  showError("runtime.connect", err);
  throw err;
});

// ── the two channels ──────────────────────────────────────────────────────
//
// Same method set, same arguments, same return shapes. `calls` documents
// what each method does on its channel; the interface table is rendered
// from it.

const hostChannel = {
  id: "host",
  label: "Host API",
  calls: {
    create: "anna.agent.session(req)",
    attach: "anna.agent.session.attach(uuid) + .refresh()",
    list: "anna.agent.session.list(opts)",
    refresh: "handle.refresh()",
    run: "handle.run({content, run_id}) — frames stream to the page",
    cancel: "handle.cancel(run_id)",
    history: "handle.history()",
    delete: "handle.delete()",
    run_status: "handle.runStatus(run_id)",
    frames: "anna.agent.session.frames({stream_id, after_seq})",
    catalog: "anna.agent.session.catalog()",
  },
  async handle(uuid) {
    // Client-side re-bind of a uuid — no RPC.
    return (await annaReady).agent.session.attach(uuid);
  },
  async create(req) {
    const h = await (await annaReady).agent.session(req);
    return {
      app_session_uuid: h.app_session_uuid,
      submode: h.submode,
      fixed_client_id: h.fixed_client_id,
      granted_tools: h.granted_tools,
      inherit_host_tools: h.inherit_host_tools,
      expires_at: h.expires_at,
      max_lifetime_at: h.max_lifetime_at,
      idle_ttl_seconds: h.idle_ttl_seconds,
    };
  },
  async attach(uuid) {
    // attach() itself is local; the refresh proves the session is reachable.
    const info = await (await this.handle(uuid)).refresh();
    return { ...info, app_session_uuid: uuid };
  },
  async list(opts) {
    const r = await (await annaReady).agent.session.list(opts);
    return (r && r.sessions) || [];
  },
  async refresh(uuid) {
    return (await this.handle(uuid)).refresh();
  },
  async *run(uuid, { content, run_id }) {
    yield* (await this.handle(uuid)).run({ content, run_id });
  },
  async cancel(uuid, runId) {
    return (await this.handle(uuid)).cancel(runId);
  },
  async history(uuid) {
    return (await this.handle(uuid)).history();
  },
  async delete(uuid) {
    return (await this.handle(uuid)).delete();
  },
  async run_status(uuid, runId) {
    return (await this.handle(uuid)).runStatus(runId);
  },
  async frames(args) {
    return (await annaReady).agent.session.frames(args);
  },
  async catalog() {
    return (await annaReady).agent.session.catalog();
  },
};

// Host error codes that mean "the Executa cannot be reached", as opposed to
// "the Executa answered with an error".
const EXECUTA_DOWN_CODES = new Set(["executa_unavailable", "executa_not_deployed", "permission_denied"]);

// One agent_session(op) call on the bundled Executa. The Executa answers
// in-band — {ok:true, result} or {ok:false, error:{code, name, message}} —
// so session-level errors keep their code on every host.
async function invokeExecuta(op, args = {}, timeoutMs = undefined) {
  const anna = await annaReady;
  const payload = { tool_id: EXECUTA_TOOL_ID, method: "agent_session", args: { op, ...args } };
  let opts;
  if (timeoutMs !== undefined) {
    // Into the payload (server-side deadline) AND the SDK's local timer.
    payload.timeoutMs = timeoutMs;
    opts = { timeoutMs: timeoutMs + 5000 };
  }
  let reply;
  try {
    reply = await anna.tools.invoke(payload, opts);
  } catch (err) {
    if (EXECUTA_DOWN_CODES.has(err && err.code)) {
      setExecutaAvailability(`tools.invoke failed with ${err.code}: ${err.message}`);
    }
    throw err;
  }
  if (reply && reply.ok === false) {
    const e = reply.error || {};
    throw Object.assign(new Error(e.message || "agent session error"), {
      name: e.name || "AgentError",
      code: e.code,
    });
  }
  return reply && reply.result;
}

const executaChannel = {
  id: "executa",
  label: "Reverse RPC",
  calls: {
    create: "client.create(...) → agent/session.create",
    attach: "client.attach(uuid) → agent/session.refresh",
    list: "client.list(...) → agent/session.list",
    refresh: "client.refresh(uuid) → agent/session.refresh",
    run: "session.run(content, run_id=…) → agent/session.run — frames stream to the Executa",
    cancel: "session.cancel(run_id) → agent/session.cancel",
    history: "session.history() → agent/session.history",
    delete: "session.delete() → agent/session.delete",
    run_status: "client.run_status(uuid, run_id) → agent/session.run.status",
    frames: "client.frames(stream_id, after_seq=…) → agent/session.frames",
    catalog: "client.catalog() → agent/session.catalog",
  },
  create: (req) => invokeExecuta("create", req),
  attach: (uuid) => invokeExecuta("attach", { app_session_uuid: uuid }),
  async list(opts) {
    return (await invokeExecuta("list", opts)).sessions || [];
  },
  refresh: (uuid) => invokeExecuta("refresh", { app_session_uuid: uuid }),
  async *run(uuid, { content, run_id }) {
    const r = await invokeExecuta(
      "run",
      { app_session_uuid: uuid, content, run_id },
      EXECUTA_RUN_TIMEOUT_MS,
    );
    yield* r.frames || [];
    // What only this channel can report: when the Executa saw its first frame.
    if (r.first_frame_ms != null) {
      yield {
        event: "channel_note",
        text: `the Executa received its first frame after ${r.first_frame_ms}ms of a ${r.elapsed_ms}ms turn (${(r.frames || []).length} frames) — live for the Executa, delivered to the page in one answer`,
      };
    }
  },
  cancel: (uuid, runId) => invokeExecuta("cancel", { app_session_uuid: uuid, run_id: runId }),
  history: (uuid) => invokeExecuta("history", { app_session_uuid: uuid }),
  delete: (uuid) => invokeExecuta("delete", { app_session_uuid: uuid }),
  run_status: (uuid, runId) => invokeExecuta("run_status", { app_session_uuid: uuid, run_id: runId }),
  frames: (args) => invokeExecuta("frames", args),
  catalog: () => invokeExecuta("catalog"),
};

const channels = { host: hostChannel, executa: executaChannel };
const INTERFACES = Object.keys(hostChannel.calls);
let channel = hostChannel;
// null = usable; otherwise the reason the Reverse RPC channel is off.
let executaUnavailable = null;

function renderInterfaces() {
  const table = $("interface-table");
  const cell = (tag, text, cls) => {
    const el = document.createElement(tag);
    el.textContent = text;
    if (cls) el.className = cls;
    return el;
  };
  const cls = (ch) =>
    [ch === channel ? "active" : "", ch === executaChannel && executaUnavailable ? "off" : ""].join(" ").trim();
  const head = document.createElement("tr");
  head.append(
    cell("th", "interface"),
    cell("th", hostChannel.label, cls(hostChannel)),
    cell("th", executaChannel.label, cls(executaChannel)),
  );
  const rows = INTERFACES.map((name) => {
    const tr = document.createElement("tr");
    tr.append(
      cell("td", name),
      cell("td", hostChannel.calls[name], cls(hostChannel)),
      cell("td", executaChannel.calls[name], cls(executaChannel)),
    );
    return tr;
  });
  table.replaceChildren(head, ...rows);
  $("channel-hint").textContent = CHANNEL_HINTS[channel.id];
}

// The Executa is optional: the app works without it, on the Host API alone.
function setExecutaAvailability(reason) {
  executaUnavailable = reason || null;
  const opt = channelSel.querySelector('option[value="executa"]');
  opt.disabled = Boolean(executaUnavailable);
  if (executaUnavailable && channel === executaChannel) {
    channel = hostChannel;
    channelSel.value = "host";
  }
  channelStatusEl.textContent = executaUnavailable
    ? `Reverse RPC is off — ${executaUnavailable}. The Host API channel is unaffected.`
    : "";
  renderInterfaces();
}

// tools.list() names the Executas this window may invoke; hosts that track
// deployment also report a per-tool status.
async function checkExecuta() {
  try {
    const r = await (await annaReady).tools.list();
    const entry = ((r && r.tools) || []).find((t) => t.tool_id === EXECUTA_TOOL_ID);
    if (!entry) {
      setExecutaAvailability(`the optional bundled Executa "${EXECUTA_HANDLE}" is not installed for this app`);
    } else if (entry.status && entry.status !== "available") {
      setExecutaAvailability(`the bundled Executa is ${entry.status} on your agent`);
    } else {
      setExecutaAvailability(null);
    }
  } catch (err) {
    setExecutaAvailability(`tools.list failed: ${(err && err.message) || err}`);
  }
}

// ── errors ────────────────────────────────────────────────────────────────

function showError(label, err) {
  const code = (err && (err.errorType || err.code || err.error?.code)) || "unknown";
  const name = (err && (err.name || err.error?.name)) || "";
  const msg = (err && (err.message || err.error?.message)) || String(err);
  let hint = "";
  if (name === "APP_SESSION_EXPIRED" || name === "APP_SESSION_REVOKED") {
    hint = " — session is gone; create a new one.";
  } else if (name === "APP_SESSION_TOKEN_EXPIRED") {
    hint = " — token lapsed; click refresh or just retry.";
  } else if (err && err.errorType === "empty_completion") {
    hint = " — infrastructure hiccup (model returned nothing); retry or pick another model.";
  } else if (name === "APP_CONCURRENCY_LIMIT" || (err && err.code === "APP_CONCURRENCY_LIMIT")) {
    hint = " — you already have the max number of concurrent agent runs (10/user); wait for one to finish or cancel it, then retry.";
  }
  errBox.textContent = `[${channel.label} · ${label}] ${name && name !== "Error" ? name : code}: ${msg}${hint}`;
}

const clearError = () => { errBox.textContent = "(none)"; };

// "This session is not reachable from here" — the answer for a session that
// does not exist, expired, was revoked, or belongs to another host. The two
// channels word it differently (APP_SESSION_NOT_FOUND / -32042 …).
function isSessionGone(err) {
  const text = [err && err.name, err && err.code, err && err.message].map((v) => String(v ?? "")).join(" ");
  return /SESSION_(NOT_FOUND|EXPIRED|REVOKED)|session[ _](not[ _]found|expired|revoked)|unknown app_session_uuid|-3204[2]|-3201[137]/i.test(text);
}

// ── lifecycle + runtime-accurate tool surface ─────────────────────────────

function renderLifecycle(info) {
  const i = info || {};
  const parts = [];
  if (i.expires_at) parts.push(`idle-expires ${i.expires_at}`);
  if (i.max_lifetime_at) parts.push(`hard-cap ${i.max_lifetime_at}`);
  if (i.idle_ttl_seconds != null) parts.push(`idle-ttl ${i.idle_ttl_seconds}s`);
  if (!parts.length && i.expires_in != null) parts.push(`token ttl ${i.expires_in}s`);
  lifecycleEl.textContent = parts.length ? `lifecycle: ${parts.join("  ·  ")}` : "lifecycle: (none)";
}

// create / run_meta carry the tools the session can REALLY execute — shown
// exactly as reported. For a file-editing app this check is NOT optional:
// with zero tools the agent is text-only and every claimed side effect is
// hallucinated. Inside an App a session gets the APP's declared tools on
// both channels; a host without that rule reports inherited host tools for
// a session the Executa created, and this line says so.
function renderToolSurface(info) {
  if (!info || !Array.isArray(info.granted_tools)) {
    toolsEl.textContent = "tools: (unknown — run or re-create to find out)";
    toolsWarnEl.hidden = true;
    return;
  }
  const inherit = info.inherit_host_tools ?? info.granted_tools.includes("*");
  if (inherit) {
    toolsEl.textContent = "tools: * — inherits the conversation's host tools; file edits are REAL";
    toolsWarnEl.hidden = true;
  } else if (info.granted_tools.length) {
    toolsEl.textContent = `tools: ${info.granted_tools.join(", ")} (the app's declared allow-list)`;
    toolsWarnEl.hidden = true;
  } else {
    toolsEl.textContent = "tools: NONE — text-only sandbox";
    toolsWarnEl.textContent =
      "NO_TOOLS_AVAILABLE: this session resolved ZERO executable tools. The walkthrough " +
      "below cannot touch real files — any write/verify output would be hallucinated. " +
      "Declaration is consent: declare the tools in manifest ui.host_api.agent.tools " +
      "(this demo declares fs_read_file / fs_list_directory / fs_write_file), then re-create.";
    toolsWarnEl.hidden = false;
  }
}

function handleRunMeta(frame, outEl) {
  renderToolSurface(frame);
  const tools = frame.inherit_host_tools
    ? "* (host tools)"
    : (frame.granted_tools || []).join(", ") || "NONE";
  const model = frame.model ? ` model=${frame.model}` : "";
  outEl.textContent += `[run_meta] run=${frame.run_id || "?"} submode=${frame.submode || "?"} tools=${tools}${model}\n`;
  for (const w of frame.warnings || []) {
    outEl.textContent += `⚠️ ${w.code}: ${w.message}\n`;
  }
}

// ── session state ─────────────────────────────────────────────────────────

// The uuid box is the single source of truth, so the user can act on ANY
// session (created, typed in, or picked from list()) — on either channel.
const sess = { runId: null, streamId: null, root: null, writtenPath: null };

const currentUuid = () => (uuidInput.value || "").trim();

function syncButtons() {
  const active = currentUuid().length > 0;
  for (const id of ["attach-btn", "refresh-btn", "delete-btn", "history-btn", "run-btn", "cancel-btn", "discover-btn", "probe-btn"]) {
    $(id).disabled = !active;
  }
  // write needs a discovered root; verify additionally needs a written path.
  $("write-btn").disabled = !active || !sess.root;
  $("verify-btn").disabled = !active || !sess.writtenPath;
  // recovery is keyed by the LAST run (forum /t/341 P3); frames needs the
  // archived stream id that run status reports.
  $("status-btn").disabled = !active || !sess.runId;
  $("frames-btn").disabled = !active || !sess.streamId;
  statusEl.textContent = active ? `session: ${currentUuid()}` : "no session";
  for (const b of sessionListEl.querySelectorAll("button")) {
    b.classList.toggle("active", b.dataset.uuid === currentUuid());
  }
}

function resetRunState() {
  sess.runId = null;
  sess.streamId = null;
}

// A different session is a different workspace context.
function resetWalkthrough() {
  sess.root = null;
  sess.writtenPath = null;
  rootStatusEl.textContent = "workspace root: (unknown)";
  writeTargetEl.textContent = "target: (discover the root first)";
  verdictEl.hidden = true;
}

function setUuid(uuid) {
  uuidInput.value = uuid || "";
  syncButtons();
}

function forgetSession() {
  resetRunState();
  resetWalkthrough();
  setUuid("");
  renderLifecycle(null);
  renderToolSurface(null);
}

uuidInput.addEventListener("input", () => {
  resetRunState();
  resetWalkthrough();
  renderToolSurface(null);
  syncButtons();
});

// ── channel selector ──────────────────────────────────────────────────────

// Bind the uuid in the box on the current channel. Reachable → carry on with
// the same session; "not found" → the session does not belong to this
// channel's host, so drop it and say so. No environment probing.
async function attachCurrent(reason) {
  const uuid = currentUuid();
  if (!uuid) return;
  try {
    const info = await channel.attach(uuid);
    renderLifecycle(info);
    channelStatusEl.textContent = `${reason}: attached ${uuid} over ${channel.label} — same session, carry on.`;
    $("setup-out").textContent = JSON.stringify(info, null, 2);
  } catch (err) {
    if (!isSessionGone(err)) throw err;
    forgetSession();
    channelStatusEl.textContent =
      `${reason}: ${uuid} is not reachable over ${channel.label} (${err.message}) — cleared. ` +
      "Sessions are shared between the page and its Executas only when the same App hosts both; create a new session on this channel.";
  }
}

channelSel.addEventListener("change", async () => {
  clearError();
  channel = channels[channelSel.value];
  channelStatusEl.textContent = "";
  renderInterfaces();
  try {
    await attachCurrent("channel switch");
  } catch (err) {
    showError("attach", err);
  }
});

// ── 1. session management ─────────────────────────────────────────────────

submodeSel.addEventListener("change", () => {
  $("submode-hint").textContent = SUBMODE_HINTS[submodeSel.value] || "";
  fixedRow.hidden = submodeSel.value !== "fixed";
});

$("create-btn").addEventListener("click", async () => {
  clearError();
  try {
    const req = {
      submode: submodeSel.value,
      system_prompt: ($("session-system-prompt").value || "").trim() || undefined,
      label: "session-demo",
    };
    if (req.submode === "fixed") {
      const cid = ($("fixed-client-input").value || "").trim();
      if (!cid) throw new Error("fixed_client_id required for submode=fixed");
      req.fixed_client_id = cid;
    }
    const info = await channel.create(req);
    resetRunState();
    resetWalkthrough();
    setUuid(info.app_session_uuid || "");
    renderLifecycle(info);
    renderToolSurface(info);
    $("setup-out").textContent = JSON.stringify(info, null, 2);
  } catch (err) {
    showError("create", err);
  }
});

$("attach-btn").addEventListener("click", async () => {
  clearError();
  try {
    await attachCurrent("attach");
  } catch (err) {
    showError("attach", err);
  }
});

$("refresh-btn").addEventListener("click", async () => {
  clearError();
  try {
    const r = await channel.refresh(currentUuid());
    renderLifecycle(r);
    $("setup-out").textContent = JSON.stringify(r, null, 2);
  } catch (err) {
    showError("refresh", err);
  }
});

$("delete-btn").addEventListener("click", async () => {
  clearError();
  try {
    // delete revokes the session AND cancels all of its active runs
    // (queued runs are dropped, running runs stop at the next checkpoint)
    // — no need to cancel() each run_id first for a clean teardown.
    await channel.delete(currentUuid());
    forgetSession();
    $("setup-out").textContent = "(session deleted — active runs cancelled)";
  } catch (err) {
    showError("delete", err);
  }
});

$("history-btn").addEventListener("click", async () => {
  clearError();
  try {
    $("setup-out").textContent = JSON.stringify(await channel.history(currentUuid()), null, 2);
  } catch (err) {
    showError("history", err);
  }
});

// Inside an App both channels list the same sessions — the App's.
$("list-btn").addEventListener("click", async () => {
  clearError();
  try {
    const sessions = await channel.list({ include_expired: false, limit: 50 });
    sessionListEl.replaceChildren();
    for (const s of sessions) {
      const uuid = s.app_session_uuid || s.uuid;
      if (!uuid) continue;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.dataset.uuid = uuid;
      const tail = uuid.length > 14 ? `…${uuid.slice(-10)}` : uuid;
      btn.textContent = s.label ? `${s.label} (${tail})` : tail;
      btn.title = uuid;
      btn.addEventListener("click", () => {
        resetRunState();
        resetWalkthrough();
        renderToolSurface(null);
        setUuid(uuid);
        renderLifecycle(s);
      });
      sessionListEl.appendChild(btn);
    }
    $("setup-out").textContent = JSON.stringify(sessions, null, 2);
    syncButtons();
  } catch (err) {
    showError("list", err);
  }
});

// Pre-create discovery: which platform tools a session created RIGHT NOW on
// this channel would resolve. blocked_by "manifest" → declare the tool in
// ui.host_api.agent.tools (or ["*"]) and republish.
$("catalog-btn").addEventListener("click", async () => {
  clearError();
  try {
    const cat = await channel.catalog();
    const tools = cat.platform_tools || [];
    const lines = tools.map((t) =>
      t.eligible ? `✅ ${t.name}` : `🚫 ${t.name} — blocked_by: ${t.blocked_by}`,
    );
    lines.push(
      "",
      `declared: ${(cat.manifest_declared || []).join(", ") || "(none)"}${cat.declared_wildcard ? '  (["*"])' : ""}`,
    );
    if (cat.inherit_host_tools) {
      lines.push("inherit_host_tools: sessions created here ALSO inherit the conversation's tool kit (not enumerated).");
    }
    $("setup-out").textContent = lines.join("\n");
  } catch (err) {
    showError("catalog", err);
  }
});

// ── shared run helper ─────────────────────────────────────────────────────

// A run that ends without any output/tool activity is surfaced by the host
// as an in-run error frame with this error_type (forum /t/191). It means
// the upstream model returned an empty completion — infrastructure, not
// "the agent chose to do nothing" — so the right app reaction is retry /
// switch model, NOT a business-level failure like "file not modified".
const EMPTY_COMPLETION = "empty_completion";

class RunError extends Error {
  constructor(message, { errorType, code, cancelled = false } = {}) {
    super(message);
    this.name = "RunError";
    this.errorType = errorType || null; // in-run: quota_exhausted, empty_completion, …
    this.code = code || null;           // gate/infra: queue_timeout, session_revoked, …
    this.cancelled = cancelled;
  }
}

const newRunId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(8));
  return `run_${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}`;
};

// What one frame means. The two channels deliver the same events in two
// shapes: the page gets the OpenAI-style chunk itself, an Executa gets it
// normalized ({event:"delta", text} …) with the chunk under `raw`. Both are
// read here by structure, so the callers never ask which channel they are on.
function readFrame(frame) {
  const ev = frame.event;
  if (ev === "queued" || ev === "started") return { kind: "status", label: ev };
  if (ev === "run_meta") return { kind: "meta" };
  if (ev === "channel_note") return { kind: "note", text: frame.text };
  if (ev === "error") return { kind: "gate_error", code: frame.code, message: frame.message };
  if (ev === "delta" && typeof frame.text === "string") return { kind: "text", text: frame.text };
  const chunk = frame.raw && typeof frame.raw === "object" ? frame.raw : frame;
  if (chunk.error) return { kind: "run_error", message: chunk.error, errorType: chunk.error_type };
  const delta = chunk.choices?.[0]?.delta;
  if (typeof delta?.content === "string" && delta.content) return { kind: "text", text: delta.content };
  if (delta?.task_cancelled) return { kind: "cancelled", reason: delta.task_cancelled.reason };
  if (delta?.task_complete) return { kind: "complete", info: delta.task_complete };
  return { kind: "other" };
}

// Runs one turn on the current channel into outEl (prompt echoed first) and
// resolves with the concatenated text — the walkthrough steps parse JSON out
// of it. Classifies EVERY way a run can terminate (practice 5):
//   • assistant text   → collected + returned
//   • in-run error     → RunError with errorType (empty_completion …)
//   • gate error       → RunError with code (queue_timeout …)
//   • task_cancelled   → RunError with cancelled=true
//   • task_complete    → usage line (proof the run really billed work)
// The app picks the run_id up front, so cancel / run status can name the run
// while it is still in flight — on either channel.
async function runAndCollect(prompt, outEl) {
  const uuid = currentUuid();
  sess.runId = newRunId();
  sess.streamId = null;
  syncButtons();
  outEl.textContent = `>>> prompt (${channel.label}, run_id=${sess.runId}):\n${prompt}\n\n<<< reply:\n`;
  let text = "";
  for await (const frame of channel.run(uuid, { content: prompt, run_id: sess.runId })) {
    const f = readFrame(frame);
    if (f.kind === "status") {
      outEl.textContent += `[${f.label}]\n`;
    } else if (f.kind === "meta") {
      handleRunMeta(frame, outEl);
    } else if (f.kind === "text") {
      text += f.text;
      outEl.textContent += f.text;
    } else if (f.kind === "complete") {
      const u = f.info.token_usage;
      const m = f.info.model ? ` model=${f.info.model}` : "";
      if (u) outEl.textContent += `\n[usage] tokens=${u.total_tokens ?? "?"}${m}`;
    } else if (f.kind === "note") {
      outEl.textContent += `\n[channel] ${f.text}`;
    } else if (f.kind === "run_error") {
      throw new RunError(f.message, { errorType: f.errorType });
    } else if (f.kind === "gate_error") {
      throw new RunError(f.message || "run error", { code: f.code });
    } else if (f.kind === "cancelled") {
      throw new RunError(f.reason || "run cancelled", { cancelled: true });
    }
  }
  outEl.textContent += "\n(done)";
  return text;
}

// Extract the last JSON object from model text. Tolerates markdown fences
// and prose around the JSON (models don't always follow "JSON only").
function extractJson(text) {
  const cleaned = text.replace(/```(?:json)?/gi, "");
  for (let start = cleaned.indexOf("{"); start !== -1; start = cleaned.indexOf("{", start + 1)) {
    for (let end = cleaned.lastIndexOf("}"); end > start; end = cleaned.lastIndexOf("}", end - 1)) {
      try {
        return JSON.parse(cleaned.slice(start, end + 1));
      } catch {
        /* keep shrinking */
      }
    }
  }
  return null;
}

// Join an absolute root and a relative tail without doubling slashes.
const joinPath = (root, tail) => `${root.replace(/\/+$/, "")}/${tail}`;

// ── 2. workspace walkthrough ──────────────────────────────────────────────

// Step 1: discover the workspace root.
const DISCOVER_PROMPT = `Report the canonical ABSOLUTE path of the workspace root your filesystem tools operate on (list it with your directory tool and use the exact absolute path from the tool response — do not guess from your home directory). Reply with ONLY this JSON on one line: {"workspace_root": "<canonical absolute path>"}`;

$("discover-btn").addEventListener("click", async () => {
  clearError();
  try {
    const text = await runAndCollect(DISCOVER_PROMPT, $("discover-out"));
    const j = extractJson(text);
    const root = j && typeof j.workspace_root === "string" ? j.workspace_root.trim() : "";
    if (root && root.startsWith("/")) {
      sess.root = root;
      rootStatusEl.textContent = `workspace root: ${root}`;
      writeTargetEl.textContent = `target: ${joinPath(root, `session-demo/proof-${nonce()}.txt`)}`;
    } else {
      sess.root = null;
      rootStatusEl.textContent = "workspace root: (could not parse an absolute path — see output)";
    }
    syncButtons();
  } catch (err) {
    showError("walkthrough.discover", err);
  }
});

// Step 2: write + nonce-verified read-back.
const nonce = () => ($("nonce-input").value || "").trim() || "demo-nonce-0001";

$("nonce-random-btn").addEventListener("click", () => {
  $("nonce-input").value = `nonce-${Math.random().toString(36).slice(2, 10)}`;
  if (sess.root) {
    writeTargetEl.textContent = `target: ${joinPath(sess.root, `session-demo/proof-${nonce()}.txt`)}`;
  }
  // A new nonce invalidates any previous write/verify pairing.
  sess.writtenPath = null;
  verdictEl.hidden = true;
  syncButtons();
});

$("write-btn").addEventListener("click", async () => {
  clearError();
  verdictEl.hidden = true;
  try {
    if (!sess.root) throw new Error("run discover first — write instructions must embed the real absolute root");
    const target = joinPath(sess.root, `session-demo/proof-${nonce()}.txt`);
    writeTargetEl.textContent = `target: ${target}`;
    const prompt =
      `Create the file at this EXACT absolute path: ${target}\n` +
      `The file content must be exactly this single line: ${nonce()}\n` +
      `Use the absolute path verbatim — do not rewrite it or choose another directory. ` +
      `On success reply with ONLY this JSON: {"written": "<the absolute path from the tool response>"}. ` +
      `If the write fails, reply with the tool's structured error as JSON, verbatim.`;
    const text = await runAndCollect(prompt, $("write-out"));
    const j = extractJson(text);
    // Track what the agent CLAIMS it wrote; the read-back will prove or refute it.
    sess.writtenPath = (j && typeof j.written === "string" && j.written.trim()) || target;
    syncButtons();
  } catch (err) {
    showError("walkthrough.write", err);
  }
});

$("verify-btn").addEventListener("click", async () => {
  clearError();
  try {
    if (!sess.writtenPath) throw new Error("run write first");
    const prompt =
      `Read the file back at this EXACT absolute path: ${sess.writtenPath}\n` +
      `Reply with ONLY this JSON: {"path": "<absolute path>", "content": "<exact file content>"}. ` +
      `If the read fails, reply with the tool's structured error as JSON, verbatim. ` +
      `Never search other directories for a similarly named file.`;
    const text = await runAndCollect(prompt, $("write-out"));
    const j = extractJson(text);
    const got = j && typeof j.content === "string" ? j.content.trim() : null;
    const pass = got !== null && got.includes(nonce());
    verdictEl.hidden = false;
    verdictEl.classList.toggle("ok", pass);
    verdictEl.classList.toggle("warn", !pass);
    verdictEl.textContent = pass
      ? `✅ VERIFIED — the read-back content contains the nonce "${nonce()}". The write really happened at ${sess.writtenPath}.`
      : `❌ NOT VERIFIED — the read-back did not return the nonce "${nonce()}". Treat the write as NOT done, regardless of what the previous run claimed. Inspect the output (structured error? wrong path? zero tools?).`;
  } catch (err) {
    showError("walkthrough.verify", err);
  }
});

// Step 3: out-of-root probe.
const PROBE_PATH = "/session-demo-out-of-root-probe/probe.txt";
const PROBE_PROMPT =
  `Attempt to read the file at this EXACT absolute path, exactly once: ${PROBE_PATH}\n` +
  `This path is intentionally outside your workspace and is expected to fail. ` +
  `Reply with ONLY the tool's error response as JSON, verbatim — include error_code, path, and sandbox_root if present. ` +
  `Do NOT retry with a different path, do NOT search for the file elsewhere, do NOT read any other file instead.`;

$("probe-btn").addEventListener("click", async () => {
  clearError();
  try {
    const text = await runAndCollect(PROBE_PROMPT, $("probe-out"));
    const j = extractJson(text);
    if (j && j.error_code) {
      $("probe-out").textContent +=
        `\n\n[app] structured error surfaced: error_code=${j.error_code}` +
        (j.sandbox_root ? ` sandbox_root=${j.sandbox_root}` : "") +
        " — this is the correct stop-and-report behaviour.";
    }
  } catch (err) {
    showError("walkthrough.probe", err);
  }
});

// ── 3. freeform run / cancel / terminal-state handling ────────────────────

// Practice 5 in action: one retry on empty_completion (an infrastructure
// hiccup — the model returned nothing), and cancellation rendered as a
// distinct outcome instead of an error. Anything else is a real error.
$("run-btn").addEventListener("click", async () => {
  clearError();
  const outEl = $("run-out");
  const prompt = $("run-input").value || "hello";
  for (let attempt = 1; ; attempt++) {
    try {
      await runAndCollect(prompt, outEl);
      return;
    } catch (err) {
      if (err instanceof RunError && err.cancelled) {
        outEl.textContent += `\n\n[cancelled] ${err.message} — the host stopped the run (task_cancelled + end frames). Not an error.`;
        return;
      }
      if (err instanceof RunError && err.errorType === EMPTY_COMPLETION && attempt === 1) {
        outEl.textContent += `\n\n[${EMPTY_COMPLETION}] ${err.message}\n[app] retryable infrastructure error — retrying once…\n`;
        continue;
      }
      showError("run", err);
      return;
    }
  }
});

// cancel(run_id) is honoured server-side: a still-queued run is dropped
// before it starts; a running run stops at the next poll checkpoint (an
// in-flight provider call finishes first). {cancelled:true} is the ack that
// the signal was recorded — the run itself reports task_cancelled when it
// actually stops. On the Reverse RPC channel this is a second tools.invoke,
// answered while the one holding the run is still in flight.
$("cancel-btn").addEventListener("click", async () => {
  clearError();
  try {
    if (!sess.runId) throw new Error("nothing to cancel — start a run first");
    const res = await channel.cancel(currentUuid(), sess.runId);
    $("run-out").textContent +=
      `\n\n[cancel] ${JSON.stringify(res)} — signal recorded for ${sess.runId}; the run ends with task_cancelled.`;
  } catch (err) {
    showError("cancel", err);
  }
});

// ── 4. zero-frame recovery: run status → frames replay (forum /t/341 P3) ──

// Push pairs with pull: ALWAYS check run status before re-running a silent
// run — "completed" means it executed and was billed; recover its output
// via frames instead of burning quota on a re-run. The archived stream id
// comes from HERE on both channels (the id inside a Reverse RPC run answer
// is host-local and cannot be replayed).
$("status-btn").addEventListener("click", async () => {
  clearError();
  const outEl = $("recover-out");
  try {
    const st = await channel.run_status(currentUuid(), sess.runId);
    sess.streamId = st.stream_id || sess.streamId;
    outEl.textContent = JSON.stringify(st, null, 2);
    const advice = {
      completed: "✅ the run executed and was billed — recover its output via [replay frames], do NOT re-run",
      running: "⏳ still executing — poll frames; do NOT start a duplicate run",
      queued: "⏳ waiting for a worker (queue wait can reach 120s) — be patient before assuming failure",
      failed: "❌ re-running is safe — this run produced no billed result",
      cancelled: "🚫 cancelled — re-run if it was unintentional",
    }[st.status];
    if (advice) outEl.textContent += `\n\n[app] ${advice}`;
    syncButtons();
  } catch (err) {
    // not found = unknown run / another host's run / older than the 1h window.
    showError("run_status", err);
  }
});

// Pull-based replay of the archived stream — works with the realtime leg
// completely dead. Pages by after_seq until a frame carries done:true.
$("frames-btn").addEventListener("click", async () => {
  clearError();
  const outEl = $("recover-out");
  try {
    outEl.textContent = `replaying ${sess.streamId} from the archive over ${channel.label}…\n\n`;
    let after = 0;
    let text = "";
    let done = false;
    for (let page = 0; page < 40 && !done; page++) {
      const { frames = [], complete } = await channel.frames({ stream_id: sess.streamId, after_seq: after });
      for (const f of frames) {
        after = f.seq;
        if (f.done) done = true;
        const read = readFrame(f.payload || {});
        if (read.kind === "text") text += read.text;
      }
      if (!done && (complete || frames.length === 0)) break; // archive tail
    }
    outEl.textContent += text || "(no text frames in the archive for this stream)";
    outEl.textContent += done
      ? `\n\n[app] ✅ terminal frame reached at seq=${after} — full output recovered WITHOUT re-running.`
      : `\n\n[app] archive tail at seq=${after} without a done frame — the run may still be executing (check [run status]).`;
  } catch (err) {
    // rate limited = shared 30/min/user budget with the host's own recovery
    // machinery — back off and retry.
    showError("frames", err);
  }
});

// ── init ──────────────────────────────────────────────────────────────────

$("session-system-prompt").value = DEFAULT_SYSTEM_PROMPT;
$("submode-hint").textContent = SUBMODE_HINTS[submodeSel.value] || "";
fixedRow.hidden = submodeSel.value !== "fixed";
renderInterfaces();
syncButtons();

annaReady.then((anna) => {
  checkExecuta();
  // Deploy reconciliation just changed which tools the agent has.
  anna.tools.onChanged?.(() => checkExecuta());
}, () => {});
